INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Mengelola File Terasa Lambat dan Berantakan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak pengguna Windows membuka File Explorer setiap hari, tetapi hanya memakai cara paling dasar: klik folder satu per satu, menyeret file dengan mouse, dan mencari dokumen dengan menggulir daftar panjang. Akibatnya pekerjaan sederhana seperti memindahkan foto atau mencari arsip lama memakan waktu berkali-kali lipat. Padahal File Explorer menyimpan banyak fitur tersembunyi yang bisa memangkas waktu kerja hingga separuhnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: File Explorer Lebih Canggih dari yang Terlihat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$File Explorer bukan sekadar jendela folder. Ia punya mesin pencarian instan, riwayat navigasi, pratinjau file tanpa membuka aplikasi, tab ganda seperti peramban web, dan puluhan pintasan keyboard. Sebagian besar fitur ini sudah ada sejak Windows 10 dan disempurnakan di Windows 11, jadi kemungkinan besar komputer Anda sudah memilikinya tanpa perlu instal apa pun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Diperlukan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Komputer atau laptop dengan Windows 10 atau Windows 11$txt$, $txt$Keyboard (sebagian besar trik memakai pintasan keyboard)$txt$, $txt$File Explorer yang sudah terbuka (tekan Win + E)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: 7 Tips Tersembunyi File Explorer$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pertama, buka dua folder sekaligus dengan tab: tekan Ctrl + T untuk tab baru, lalu seret file antar tab tanpa membuka dua jendela. Kedua, cari file super cepat dengan mengetik langsung di kolom pencarian kanan atas, lalu saring memakai kata kunci seperti jenis: gambar atau diubah: minggu ini. Ketiga, pratinjau file tanpa membukanya dengan memilih file lalu menekan Alt + P; panel pratinjau muncul di kanan. Keempat, ganti nama banyak file sekaligus: pilih semuanya, tekan F2, ketik nama baru, dan Windows menomori sisanya otomatis. Kelima, kembali ke folder sebelumnya dengan Alt + panah kiri, dan maju lagi dengan Alt + panah kanan. Keenam, buka folder dalam jendela baru dengan Ctrl + N agar perbandingan dua folder lebih mudah. Ketujuh, tampilkan ekstensi file lewat menu Lihat lalu centang Ekstensi nama file supaya Anda tahu file .docx, .pdf, atau .jpg dengan pasti.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Jebakan yang Perlu Diwaspadai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Hati-hati dengan fitur ganti nama massal: sekali dijalankan sulit dibatalkan satu per satu, jadi pastikan file yang dipilih sudah benar. Jangan asal menghapus file sistem di folder Windows atau Program Files meski terlihat tidak penting; salah hapus bisa merusak aplikasi. Saat memakai pencarian dengan filter tanggal, periksa dulu zona waktu dan format tanggal agar hasil tidak meleset. Terakhir, pintasan Ctrl + X (potong) memindahkan file, bukan menyalin; pastikan tujuan tempel sudah siap sebelum memotong file penting.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tab baru terbuka dengan Ctrl + T dan file bisa diseret antar tab$txt$, $txt$Pencarian dengan filter jenis: gambar menampilkan hanya file gambar$txt$, $txt$Panel pratinjau muncul dengan Alt + P untuk dokumen dan foto$txt$, $txt$Beberapa file berhasil diganti nama sekaligus dengan F2$txt$, $txt$Ekstensi file terlihat setelah dicentang di menu Lihat$txt$, $txt$Biasakan Win + E dan pelajari satu pintasan baru setiap minggu$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Gigi Berlubang Tiba-tiba Nyeri Hebat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Nyeri gigi berlubang sering muncul di waktu yang tidak tepat: tengah malam, akhir pekan, atau saat klinik gigi tutup. Rasa ngilu berdenyut membuat sulit makan, sulit tidur, bahkan sulit berkonsentrasi. Banyak orang panik lalu mencoba cara-cara berbahaya seperti meneteskan minyak panas atau meminum antibiotik tanpa resep. Padahal ada langkah pertolongan pertama yang aman untuk meredakan nyeri sementara sampai sempat ke dokter gigi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Gigi Berlubang Terasa Sakit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Lubang gigi terbentuk ketika bakteri mengubah sisa gula menjadi asam yang mengikis email gigi. Begitu lubang mencapai lapisan dentin atau mendekati saraf (pulpa), gigi menjadi sensitif terhadap panas, dingin, dan tekanan kunyahan. Nyeri berdenyut yang tidak kunjung reda biasanya tanda peradangan saraf. Informasi ini bersifat umum dan bukan pengganti nasihat medis; diagnosis pasti hanya bisa ditegakkan dokter gigi lewat pemeriksaan langsung.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Air hangat dan garam dapur untuk berkumur$txt$, $txt$Kompres dingin (es batu dibungkus kain bersih)$txt$, $txt$Obat pereda nyeri bebas seperti parasetamol sesuai dosis kemasan$txt$, $txt$Sikat gigi berbulu lembut dan benang gigi$txt$, $txt$Nomor klinik atau dokter gigi terdekat$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Pertolongan Pertama$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pertama, berkumurlah dengan air garam hangat selama 30 detik untuk membersihkan sisa makanan di lubang gigi, lalu ludahkan. Kedua, bersihkan area gigi dengan benang gigi secara lembut; kadang nyeri berasal dari sisa makanan yang terselip. Ketiga, tempelkan kompres dingin di pipi sisi gigi yang sakit selama 15 menit untuk mengurangi bengkak dan nyeri. Keempat, minumlah pereda nyeri sesuai dosis pada kemasan bila nyeri mengganggu; jangan meletakkan tablet langsung di gusi karena bisa membakar jaringan. Kelima, hindari makanan sangat panas, sangat dingin, manis, dan keras sampai diperiksa dokter. Keenam, segera buat janji dengan dokter gigi; pertolongan ini hanya sementara, bukan penyembuhan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko, Pantangan, dan Tanda Bahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan meneteskan minyak kayu putih, bensin, atau cairan panas ke lubang gigi; semuanya bisa melukai gusi dan memperparah keadaan. Jangan minum antibiotik tanpa resep dokter karena tidak menyembuhkan lubang dan berisiko resistensi. Segera ke dokter gigi atau IGD bila muncul tanda bahaya: pipi bengkak dan memerah, demam, nyeri tidak mempan pereda nyeri, nanah keluar dari gusi, atau sulit menelan dan membuka mulut. Bila ragu, selalu konsultasikan ke dokter gigi profesional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sisa makanan di sekitar lubang sudah dibersihkan dengan kumur dan benang gigi$txt$, $txt$Nyeri mereda setelah kompres dingin dan pereda nyeri sesuai dosis$txt$, $txt$Tidak ada zat berbahaya yang dimasukkan ke lubang gigi$txt$, $txt$Jadwal kunjungan ke dokter gigi sudah dibuat$txt$, $txt$Sikat gigi dua kali sehari dan periksa rutin tiap enam bulan$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Orang Minangkabau$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Suku Minangkabau adalah masyarakat asli Sumatera Barat yang berjumlah jutaan jiwa dan tersebar di seluruh Indonesia bahkan mancanegara. Mereka terkenal dengan rumah gadang beratap gonjong, masakan rendang yang mendunia, dan satu hal yang langka di dunia: sistem kekerabatan matrilineal, di mana garis keturunan dan harta pusaka diwariskan melalui pihak ibu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Matrilineal: Sistem Kekerabatan Terbesar di Dunia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Dalam masyarakat Minang, anak mengikuti suku ibunya, dan harta pusaka kaum seperti tanah serta rumah gadang dimiliki bersama oleh perempuan satu kaum. Paman dari pihak ibu, yang disebut mamak, memegang peran penting sebagai penasihat dan wali bagi kemenakannya. Sistem ini bukan berarti perempuan berkuasa mutlak; keputusan besar diambil lewat musyawarah kaum yang dipimpin penghulu, mencerminkan prinsip demokrasi adat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Adat Basandi Syarak, Syarak Basandi Kitabullah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Falsafah hidup Minang diringkas dalam pepatah adat basandi syarak, syarak basandi Kitabullah: adat bersendikan syariat Islam, dan syariat bersendikan Al-Quran. Artinya seluruh aturan adat harus selaras dengan ajaran agama. Perpaduan ini membuat Minangkabau menjadi contoh unik bagaimana tradisi lokal dan agama dapat saling menguatkan, bukan saling meniadakan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Merantau: Tradisi yang Membentuk Karakter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Merantau, pergi meninggalkan kampung halaman untuk mencari penghidupan dan ilmu, adalah kewajiban adat bagi laki-laki Minang dewasa. Tradisi ini melahirkan perantau-perantau sukses di bidang dagang, politik, sastra, dan ilmu pengetahuan. Di rantau mereka mendirikan surau dan perkumpulan sesama perantau, sehingga identitas Minang tetap terjaga meski jauh dari kampung halaman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Warisan Budaya untuk Indonesia dan Dunia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Dari ranah Minang lahir banyak tokoh pendiri bangsa, sastrawan, dan ulama besar. Rumah gadang dengan arsitektur tanpa paku, kain songket, tari piring, dan rendang yang dinobatkan sebagai salah satu makanan terenak dunia adalah bukti kekayaan budaya mereka. Mempelajari Minangkabau berarti belajar bahwa kemajuan tidak harus mengorbankan adat, dan adat tidak harus menutup diri dari perubahan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Neon$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Neon adalah unsur kimia dengan simbol Ne dan nomor atom 10. Ia termasuk gas mulia, kelompok unsur yang sangat stabil dan hampir tidak mau bereaksi dengan unsur lain. Neon tidak berwarna dan tidak berbau, dan jumlahnya di udara sangat sedikit, hanya sekitar 18 bagian per juta. Meski langka di udara, ia terkenal karena satu sifat istimewa: memancarkan cahaya terang saat dialiri listrik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penemuan Neon$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Neon ditemukan pada tahun 1898 oleh ilmuwan Inggris William Ramsay dan Morris Travers lewat percobaan pendinginan udara hingga mencair lalu memisahkannya sedikit demi sedikit. Nama neon berasal dari bahasa Yunani neos yang berarti baru. Penemuan ini melengkapi pemahaman tentang gas mulia dan mengantarkan Ramsay meraih Hadiah Nobel Kimia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Mengapa Neon Bisa Bercahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Ketika arus listrik tegangan tinggi dialirkan melalui tabung berisi gas neon bertekanan rendah, elektron-elektron atom neon menyerap energi lalu melepaskannya kembali dalam bentuk cahaya. Cahaya neon murni berwarna merah-oranye terang yang khas. Warna-warni pada papan iklan sebenarnya berasal dari campuran gas lain seperti argon, helium, dan uap raksa, tetapi sebutan lampu neon sudah telanjur populer untuk semuanya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Neon dalam Kehidupan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Selain papan iklan, neon dipakai pada lampu indikator tegangan tinggi, rambu darurat pesawat, dan tabung laser helium-neon yang dipakai pada pemindai barcode dan peralatan laboratorium. Dalam industri, neon cair dipakai sebagai pendingin kriogenik meski lebih mahal daripada nitrogen cair. Sifatnya yang tidak reaktif juga membuatnya aman dipakai pada jendela kapal selam penelitian laut dalam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Neon dan Masa Depan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Cadangan neon dunia terbatas karena sulit diekstrak dari udara, dan sebagian besar pasokannya pernah bergantung pada sedikit negara produsen. Hal ini sempat mengguncang industri semikonduktor yang memakai laser berbasis neon untuk mencetak chip. Para ilmuwan kini mengembangkan metode daur ulang dan sumber alternatif agar cahaya terang neon tetap bisa menerangi teknologi masa depan tanpa krisis pasokan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu menjelaskan proses masuk dan berkembangnya Islam di Indonesia, menyebutkan kerajaan-kerajaan Islam beserta peninggalannya, serta menghargai warisan budaya Islam sebagai bagian dari identitas bangsa Indonesia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Materi: Masuknya Islam ke Nusantara$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Islam masuk ke Nusantara sekitar abad ke-13 melalui tiga jalur utama: perdagangan oleh saudagar dari Gujarat, Arab, dan Persia yang berdakwah lewat keteladanan akhlak; dakwah oleh para ulama dan wali; serta perkawinan antara pedagang muslim dengan putri bangsawan lokal sehingga keluarga kerajaan memeluk Islam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Materi: Samudera Pasai dan Demak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Samudera Pasai di pesisir Aceh yang berdiri sekitar abad ke-13 diakui sebagai kerajaan Islam pertama di Nusantara di bawah Sultan Malikussaleh, dengan bukti makamnya dan catatan Ibnu Batutah. Kerajaan Demak di Jawa berdiri sekitar akhir abad ke-15 di bawah Raden Patah dengan dukungan Walisongo; Masjid Agung Demak dengan saka tatalnya adalah peninggalan termasyhur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Materi: Aceh, Ternate-Tidore, dan Warisan Budaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Kesultanan Aceh Darussalam mencapai puncak di bawah Sultan Iskandar Muda pada abad ke-17 sebagai kekuatan maritim besar, sementara Ternate dan Tidore bersaing menguasai perdagangan rempah hingga kedatangan bangsa Eropa. Warisannya hidup hingga kini: masjid kuno, tradisi sekaten, seni kaligrafi, sastra hikayat, dan pesantren. Akulturasi terlihat pada arsitektur masjid beratap tumpang khas Jawa, bukti Islam Nusantara berkembang lewat jalan damai dan budaya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebutkan tiga jalur masuknya Islam ke Nusantara beserta penjelasannya!$txt$, $txt$Mengapa Samudera Pasai disebut kerajaan Islam pertama di Indonesia? Jelaskan buktinya!$txt$, $txt$Siapa pendiri Kerajaan Demak dan apa peran Walisongo di sana?$txt$, $txt$Jelaskan dua contoh akulturasi budaya Islam dengan budaya lokal di Indonesia!$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1) Perdagangan: saudagar muslim berdagang sekaligus berdakwah lewat keteladanan. 2) Dakwah: ulama dan wali menyebarkan Islam lewat pengajaran. 3) Perkawinan: pedagang muslim menikahi putri bangsawan sehingga keluarga kerajaan memeluk Islam.$txt$, $txt$Karena rajanya Sultan Malikussaleh memerintah kerajaan bercorak Islam sekitar abad ke-13; buktinya makam Sultan Malikussaleh dan catatan Ibnu Batutah.$txt$, $txt$Raden Patah; Walisongo membantu dakwah dan pembangunan, misalnya Sunan Kalijaga merancang saka tatal Masjid Agung Demak.$txt$, $txt$Arsitektur masjid beratap tumpang khas Jawa-Hindu, dan tradisi sekaten yang memadukan perayaan Islam dengan budaya keraton.$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu diharapkan bisa menjelaskan apa itu luas bangun datar, mengukur luas dengan satuan persegi, serta menghitung luas persegi dan persegi panjang dengan benar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Materi: Apa Itu Luas?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Luas adalah ukuran seberapa besar permukaan suatu bangun datar. Bayangkan lantai kamarmu: luas lantai menunjukkan berapa banyak ubin yang dibutuhkan untuk menutupinya. Luas diukur dengan satuan persegi, misalnya sentimeter persegi yang ditulis cm persegi. Satu cm persegi adalah luas sebuah persegi kecil yang panjang sisinya 1 cm.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Materi: Luas Persegi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Persegi adalah bangun datar yang keempat sisinya sama panjang. Luas persegi = sisi x sisi. Contoh: sebuah sapu tangan berbentuk persegi dengan sisi 10 cm. Luasnya = 10 x 10 = 100 cm persegi. Karena semua sisi sama, kamu cukup mengalikan satu sisi dengan dirinya sendiri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Materi: Luas Persegi Panjang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Persegi panjang punya panjang dan lebar yang berbeda. Luas persegi panjang = panjang x lebar. Contoh: kebun Pak Tani berbentuk persegi panjang, panjangnya 8 meter dan lebarnya 5 meter. Luasnya = 8 x 5 = 40 meter persegi. Ingat selalu: panjang dikali lebar, dan jangan lupa menuliskan satuan perseginya!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebuah buku berbentuk persegi dengan sisi 15 cm. Berapa luas buku itu?$txt$, $txt$Papan tulis panjangnya 200 cm dan lebarnya 100 cm. Berapa luas papan tulis?$txt$, $txt$Lantai kamar berbentuk persegi dengan sisi 4 meter. Berapa luas lantai kamar?$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Luas = 15 x 15 = 225 cm persegi.$txt$, $txt$Luas = 200 x 100 = 20000 cm persegi.$txt$, $txt$Luas = 4 x 4 = 16 meter persegi.$txt$])));
